using TownOfHost;
using TownOfHost.Roles.Core;
using TownOfHost.Roles.Core.Interfaces;
using TownOfHost.Roles.Impostor;
class Program {
 static int passed;
 static void Check(bool ok,string text="assertion"){if(!ok)throw new Exception(text);}
 static void Reset(){AmongUsClient.Instance.AmHost=true;CustomRoleManager.AllActiveRoles.Clear();CustomRoleManager.Sent.Clear();CustomRoleManager.Kills.Clear();PlayerCatch.Players.Clear();LateTask.Pending.Clear();UnityEngine.Random.Values.Clear();UnityEngine.Random.Calls=0;TownOfHost.Main.AllPlayerKillCooldown.Clear();IUsePhantomButton.IPPlayerKillCooldown.Clear();GameStates.InGame=true;GameStates.IsInTask=true;GameStates.IsMeeting=false;GameStates.CalledMeeting=false;AURoleOptions.PhantomCooldown=30;UtilsNotifyRoles.Calls=0;FloatOptionItem.Registered.Clear();Damocles.RoleInfo.OptionCreator();}
 static void Test(string name,Action test){Reset();test();passed++;Console.WriteLine("PASS "+name);}
 static PlayerControl Player(byte id){var p=new PlayerControl{PlayerId=id};PlayerCatch.Players[id]=p;return p;}
 static Damocles Role(byte id=1){var p=Player(id);PlayerControl.LocalPlayer=p;return new Damocles(p);}
 static void Click(Damocles d){bool adjust=true;bool? reset=false;((IUsePhantomButton)d).CheckOnClick(ref adjust,ref reset);Check(!adjust,"generic kill cooldown adjustment enabled");}
 static void King(Damocles d){Click(d);LateTask.RunAll();}
 static MurderInfo Kill(Damocles d,byte targetId=2){var p=Player(targetId);p.Data.IsDead=true;var info=new MurderInfo{AttemptKiller=d.Player,AttemptTarget=p,AppearanceKiller=d.Player,AppearanceTarget=p};((IKiller)d).OnMurderPlayerAsKiller(info);return info;}
 static float Chance(Damocles d)=>float.Parse(d.GetProgressText().Split(' ').Last().TrimEnd('%',')'),System.Globalization.CultureInfo.CurrentCulture);
 static void Main(){
 Test("role metadata preserves supplied ID base Phantom alias and Shell origin",()=>{var i=Damocles.RoleInfo;Check((int)i.RoleName==373&&i.ConfigId==39900&&i.BaseRoleType()==AmongUs.GameOptions.RoleTypes.Phantom&&i.CustomRoleType==CustomRoleTypes.Impostor&&i.From==From.TownOfHost_Shell&&i.ChatCommand=="dmc"&&i.IsNewRole);});
 Test("four definition defaults and option IDs are preserved",()=>{var options=FloatOptionItem.Registered.Values.ToArray();Check(options.Select(o=>o.Id).SequenceEqual(new[]{39910,39911,39912,39913}));Check(options.Select(o=>o.Value).SequenceEqual(new[]{40f,20f,5f,15f}));Check(options[0].Rule==new FloatValueRule(2.5f,100f,2.5f)&&options[2].Rule==new FloatValueRule(0f,100f,.5f)&&options[3].Rule==new FloatValueRule(.5f,100f,.5f));Check(options.Take(2).All(o=>o.Format==OptionFormat.Seconds)&&options.Skip(2).All(o=>o.Format==OptionFormat.Percent));});
 Test("normal begins at 40 seconds with no risk display",()=>{var d=Role();Check(((IKiller)d).CalculateKillCooldown()==40&&d.GetProgressText()=="");});
 Test("vent and sabotage stay available",()=>{var d=Role();Check(((IKiller)d).CanUseKillButton()&&d.CanUseImpostorVentButton()&&d.CanUseSabotageButton());});
 Test("Phantom button remains a one click non invisible mode button",()=>{var d=Role();Check(((IUsePhantomButton)d).UseOneclickButton&&((IUsePhantomButton)d).IsPhantomRole&&!((IUsePhantomButton)d).IsresetAfterKill);});
 Test("Phantom cooldown is one second only when its options are applied",()=>{var d=Role();d.ApplyGameOptions(new AmongUs.GameOptions.GameOptions());Check(AURoleOptions.PhantomCooldown==1);});
 Test("mode toggles 40 to 20 to 40 through the actual Phantom interface",()=>{var d=Role();King(d);Check(d.CalculateKillCooldown()==20&&d.Player.NativeKillTimer==20&&Chance(d)==5);Click(d);LateTask.RunAll();Check(d.CalculateKillCooldown()==40&&d.Player.NativeKillTimer==40&&d.GetProgressText()=="");});
 Test("mode cooldown is applied after Phantom restoration rather than immediately",()=>{var d=Role();Click(d);Check(d.Player.AppliedKillTimers.Count==0&&LateTask.Pending.Single().Delay==.2f);LateTask.RunAll();Check(d.Player.AppliedKillTimers.Single()==20&&d.Player.SyncCalls==1);});
 Test("rapid toggles apply only the final mode cooldown",()=>{var d=Role();Click(d);Click(d);Click(d);LateTask.RunAll();Check(d.Player.AppliedKillTimers.SequenceEqual(new[]{20f}));});
 Test("normal kills never roll increase or synchronize risk",()=>{var d=Role();Kill(d);Check(UnityEngine.Random.Calls==0&&CustomRoleManager.Sent.Count==0&&CustomRoleManager.Kills.Count==0);King(d);Check(Chance(d)==5);});
 Test("first roll uses 5 percent before adding 15",()=>{var d=Role();King(d);UnityEngine.Random.Values.Enqueue(4.99f);Kill(d);Check(Chance(d)==20&&CustomRoleManager.Kills.Count==0);LateTask.RunAll();Check(CustomRoleManager.Kills.Count==1);});
 Test("roll boundary is exclusive at 5 percent",()=>{var d=Role();King(d);UnityEngine.Random.Values.Enqueue(5f);Kill(d);LateTask.RunAll();Check(Chance(d)==20&&CustomRoleManager.Kills.Count==0);});
 Test("success chance rises per kill and caps at 100",()=>{var d=Role();King(d);for(byte id=2;id<=10;id++){UnityEngine.Random.Values.Enqueue(99.999f);Kill(d,id);}Check(Chance(d)==100&&UnityEngine.Random.Calls==9);});
 Test("zero initial chance never dies on first kill",()=>{FloatOptionItem.Registered["DamoclesStartChance"].Value=0;var d=Role();King(d);UnityEngine.Random.Values.Enqueue(0);Kill(d);LateTask.RunAll();Check(CustomRoleManager.Kills.Count==0&&Chance(d)==15);});
 Test("100 percent always schedules one self kill via host murder pipeline",()=>{FloatOptionItem.Registered["DamoclesStartChance"].Value=100;var d=Role();King(d);Kill(d);LateTask.RunAll();var k=CustomRoleManager.Kills.Single();Check(k.Killer==1&&k.Target==1&&k.Force==true&&k.DontRoleAbility==true&&k.Power==99&&k.Reason==CustomDeathReason.Suicide);});
 Test("failed and protected kills do not roll",()=>{var d=Role();King(d);var target=Player(2);target.Data.IsDead=true;foreach(var flags in new[]{(false,true),(true,false)})((IKiller)d).OnMurderPlayerAsKiller(new(){AttemptKiller=d.Player,AttemptTarget=target,AppearanceKiller=d.Player,AppearanceTarget=target,DoKill=flags.Item1,CanKill=flags.Item2});Check(UnityEngine.Random.Calls==0&&Chance(d)==5);});
 Test("non dead target notification is not a successful kill",()=>{var d=Role();King(d);var p=Player(2);((IKiller)d).OnMurderPlayerAsKiller(new(){AttemptKiller=d.Player,AttemptTarget=p,AppearanceKiller=d.Player,AppearanceTarget=p});Check(UnityEngine.Random.Calls==0);});
 Test("self kill never recursively rolls",()=>{var d=Role();King(d);((IKiller)d).OnMurderPlayerAsKiller(new(){AttemptKiller=d.Player,AttemptTarget=d.Player,AppearanceKiller=d.Player,AppearanceTarget=d.Player});Check(UnityEngine.Random.Calls==0);});
 Test("other killers and appearance aliases never use this players chance",()=>{var d=Role();King(d);var other=Player(3);var target=Player(2);target.Data.IsDead=true;foreach(var killers in new[]{(other,d.Player),(d.Player,other)})((IKiller)d).OnMurderPlayerAsKiller(new(){AttemptKiller=killers.Item1,AttemptTarget=target,AppearanceKiller=killers.Item2,AppearanceTarget=target});Check(UnityEngine.Random.Calls==0);});
 Test("same successful death rolls only once even with another info object",()=>{var d=Role();King(d);var info=Kill(d);((IKiller)d).OnMurderPlayerAsKiller(info);((IKiller)d).OnMurderPlayerAsKiller(new(){AttemptKiller=d.Player,AttemptTarget=info.AttemptTarget,AppearanceKiller=d.Player,AppearanceTarget=info.AppearanceTarget});Check(UnityEngine.Random.Calls==1&&Chance(d)==20);});
 Test("revived target can count as a later legitimate death",()=>{var d=Role();King(d);var info=Kill(d);info.AttemptTarget.Data.IsDead=false;d.OnFixedUpdate(d.Player);info.AttemptTarget.Data.IsDead=true;((IKiller)d).OnMurderPlayerAsKiller(info);Check(UnityEngine.Random.Calls==2&&Chance(d)==35);});
 Test("normal to kingship does not reset the increased chance",()=>{var d=Role();King(d);Kill(d);Click(d);LateTask.RunAll();Click(d);LateTask.RunAll();Check(Chance(d)==20);});
 Test("meeting preserves mode and probability but invalidates pending cooldown",()=>{var d=Role();Click(d);d.OnStartMeeting();LateTask.RunAll();Check(d.Player.AppliedKillTimers.Count==0&&d.CalculateKillCooldown()==20&&Chance(d)==5);});
 Test("meeting cancels pending self death even after returning to tasks",()=>{var d=Role();King(d);UnityEngine.Random.Values.Enqueue(0);Kill(d);d.OnStartMeeting();LateTask.RunAll();Check(CustomRoleManager.Kills.Count==0);});
 Test("switching mode cannot cancel a successful death roll",()=>{var d=Role();King(d);UnityEngine.Random.Values.Enqueue(0);Kill(d);Click(d);LateTask.RunAll();Check(CustomRoleManager.Kills.Count==1);});
 Test("non host never mutates mode or rolls",()=>{var d=Role();AmongUsClient.Instance.AmHost=false;Click(d);Kill(d);Check(d.CalculateKillCooldown()==40&&UnityEngine.Random.Calls==0&&CustomRoleManager.Sent.Count==0);});
 Test("dead disconnected lobby and meeting players cannot toggle",()=>{foreach(var state in Enumerable.Range(0,6)){Reset();var d=Role();if(state==0)d.Player.Data.IsDead=true;if(state==1)d.Player.Data.Disconnected=true;if(state==2)GameStates.InGame=false;if(state==3)GameStates.IsMeeting=true;if(state==4)GameStates.CalledMeeting=true;if(state==5)GameStates.IsInTask=false;Click(d);Check(d.CalculateKillCooldown()==40&&LateTask.Pending.Count==0);}});
 Test("death before deferred cooldown or suicide cancels it",()=>{foreach(var suicide in new[]{false,true}){Reset();var d=Role();if(suicide){King(d);UnityEngine.Random.Values.Enqueue(0);Kill(d);}else Click(d);d.Player.Data.IsDead=true;LateTask.RunAll();Check(CustomRoleManager.Kills.Count==0&&(!suicide?d.Player.AppliedKillTimers.Count==0:true));}});
 Test("game end prevents deferred mutations",()=>{var d=Role();Click(d);GameStates.InGame=false;LateTask.RunAll();Check(d.Player.AppliedKillTimers.Count==0);});
 Test("dispose role change and PlayerId reuse invalidate deferred work",()=>{foreach(var change in Enumerable.Range(0,3)){Reset();var d=Role();var p=d.Player;Click(d);if(change==0)d.Dispose();if(change==1)CustomRoleManager.AllActiveRoles[p.PlayerId]=new Damocles(p);if(change==2)PlayerCatch.Players[p.PlayerId]=new(){PlayerId=p.PlayerId};LateTask.RunAll();Check(p.AppliedKillTimers.Count==0);}});
 Test("multiple Damocles keep separate modes chances and cooldowns",()=>{var a=Role();var b=Role(3);King(a);Kill(a);Check(a.CalculateKillCooldown()==20&&Chance(a)==20&&b.CalculateKillCooldown()==40&&b.GetProgressText()=="");});
 Test("host state RPC is reliable and contains only mode and chance",()=>{var d=Role();Click(d);var sent=CustomRoleManager.Sent.Single();Check(sent.Option==Hazel.SendOption.Reliable&&sent.Values.Length==2&&(bool)sent.Values[0]&&(float)sent.Values[1]==5);});
 Test("non host receives the mode and chance without sending state back",()=>{var d=Role();AmongUsClient.Instance.AmHost=false;d.ReceiveRPC(new(true,35f));Check(d.CalculateKillCooldown()==20&&Chance(d)==35&&CustomRoleManager.Sent.Count==0);});
 Test("host ignores incoming role state",()=>{var d=Role();d.ReceiveRPC(new(true,100f));Check(d.CalculateKillCooldown()==40&&d.GetProgressText()=="");});
 Test("malformed NaN infinite and out of range RPC leaves old state intact",()=>{var d=Role();AmongUsClient.Instance.AmHost=false;foreach(var n in new[]{float.NaN,float.PositiveInfinity,-1f,101f}){d.ReceiveRPC(new(true,n));Check(d.CalculateKillCooldown()==40&&d.GetProgressText()=="");}});
 Test("destroyed or replaced role ignores received state",()=>{var d=Role();d.OnDestroy();AmongUsClient.Instance.AmHost=false;d.ReceiveRPC(new(true,100f));Check(d.CalculateKillCooldown()==40);});
 Test("reliable state round trip represents the same cooldown and progress",()=>{var a=Role();King(a);Kill(a);var msg=CustomRoleManager.Sent.Last();var b=Role(3);AmongUsClient.Instance.AmHost=false;b.ReceiveRPC(new(msg.Values));Check(a.CalculateKillCooldown()==b.CalculateKillCooldown()&&a.GetProgressText()==b.GetProgressText());});
 Test("new role instance starts from initial values after a prior game",()=>{var old=Role();King(old);Kill(old);old.Dispose();var d=Role();Check(d.CalculateKillCooldown()==40&&d.GetProgressText()=="");King(d);Check(Chance(d)==5);});
 Test("100 percent also kills at the random upper endpoint",()=>{FloatOptionItem.Registered["DamoclesStartChance"].Value=100;var d=Role();King(d);UnityEngine.Random.Values.Enqueue(100f);Kill(d);LateTask.RunAll();Check(CustomRoleManager.Kills.Count==1);});
 Test("same native player represented by another managed wrapper is accepted",()=>{var d=Role();PlayerCatch.Players[1]=new(){PlayerId=1,NativeIdentity=d.Player.NativeIdentity,Data=d.Player.Data};King(d);Check(d.CalculateKillCooldown()==20&&d.Player.NativeKillTimer==20);});
 Console.WriteLine($"RESULT {passed} passed, 0 failed (actual Damocles / IKiller / IUsePhantomButton; Unity, network, cooldown transport substitutes)");
 }
}

